96	func (s *Store) ListAttachments(ctx context.Context, find *FindAttachment) ([]*Attachment, error) {
97		// Set default limits to prevent loading too many attachments at once
98		shouldApplyDefaultLimit := find.Limit == nil && len(find.MemoIDList) == 0
99		if shouldApplyDefaultLimit && find.GetBlob {
100			// When fetching blobs, we should be especially careful with limits
101			defaultLimit := 10
102			find.Limit = &defaultLimit
103		} else if shouldApplyDefaultLimit {
104			// Even without blobs, let's default to a reasonable limit
105			defaultLimit := 100
106			find.Limit = &defaultLimit
107		}
108	
109		return s.driver.ListAttachments(ctx, find)
110	}
