28	func (s *Store) UpsertInstanceSetting(ctx context.Context, upsert *storepb.InstanceSetting) (*storepb.InstanceSetting, error) {
29		instanceSettingRaw := &InstanceSetting{
30			Name: upsert.Key.String(),
31		}
32		var valueBytes []byte
33		var err error
34		if upsert.Key == storepb.InstanceSettingKey_BASIC {
35			valueBytes, err = protojson.Marshal(upsert.GetBasicSetting())
36		} else if upsert.Key == storepb.InstanceSettingKey_GENERAL {
37			valueBytes, err = protojson.Marshal(upsert.GetGeneralSetting())
38		} else if upsert.Key == storepb.InstanceSettingKey_STORAGE {
39			valueBytes, err = protojson.Marshal(upsert.GetStorageSetting())
40		} else if upsert.Key == storepb.InstanceSettingKey_MEMO_RELATED {
41			valueBytes, err = protojson.Marshal(upsert.GetMemoRelatedSetting())
42		} else if upsert.Key == storepb.InstanceSettingKey_TAGS {
43			valueBytes, err = protojson.Marshal(upsert.GetTagsSetting())
44		} else if upsert.Key == storepb.InstanceSettingKey_NOTIFICATION {
45			valueBytes, err = protojson.Marshal(upsert.GetNotificationSetting())
46		} else if upsert.Key == storepb.InstanceSettingKey_AI {
47			valueBytes, err = protojson.Marshal(upsert.GetAiSetting())
48		} else {
49			return nil, errors.Errorf("unsupported instance setting key: %v", upsert.Key)
50		}
51		if err != nil {
52			return nil, errors.Wrap(err, "failed to marshal instance setting value")
53		}
54		valueString := string(valueBytes)
55		instanceSettingRaw.Value = valueString
56		instanceSettingRaw, err = s.driver.UpsertInstanceSetting(ctx, instanceSettingRaw)
57		if err != nil {
58			return nil, errors.Wrap(err, "Failed to upsert instance setting")
59		}
60		instanceSetting, err := convertInstanceSettingFromRaw(instanceSettingRaw)
61		if err != nil {
62			return nil, errors.Wrap(err, "Failed to convert instance setting")
63		}
64		s.cacheInstanceSetting(ctx, instanceSetting)
65		return instanceSetting, nil
66	}
67	
68	func (s *Store) ListInstanceSettings(ctx context.Context, find *FindInstanceSetting) ([]*storepb.InstanceSetting, error) {
69		stored, err := s.listStoredInstanceSettings(ctx, find)
70		if err != nil {
71			return nil, err
72		}
73		if find.Name != "" {
74			key, ok := storepb.InstanceSettingKey_value[find.Name]
75			if ok {
76				if configured := s.getDeploymentInstanceSetting(storepb.InstanceSettingKey(key)); configured != nil {
77					return []*storepb.InstanceSetting{configured}, nil
78				}
79			}
80			return stored, nil
81		}
82	
83		byKey := make(map[storepb.InstanceSettingKey]*storepb.InstanceSetting, len(stored))
84		for _, setting := range stored {
85			byKey[setting.Key] = setting
86		}
87		s.deploymentConfigMu.RLock()
88		for key, setting := range s.deploymentConfig.instanceSettings {
89			byKey[key] = cloneInstanceSetting(setting)
90		}
91		s.deploymentConfigMu.RUnlock()
92		settings := make([]*storepb.InstanceSetting, 0, len(byKey))
